function isCellSelected(x: number, y: number, sel: SelectionRange | null): boolean {
  if (!sel) return false;
  let [sx, sy] = sel.start;
  let [ex, ey] = sel.end;
  if (sy > ey || (sy === ey && sx > ex)) {
    [sx, sy, ex, ey] = [ex, ey, sx, sy];
  }
  if (y < sy || y > ey) return false;
  if (y === sy && y === ey) return x >= sx && x < ex;
  if (y === sy) return x >= sx;
  if (y === ey) return x < ex;
  return true;
