import type { CursorState, SelectionRange, Theme } from "./core";
import { type CellGrid, DEFAULT_THEME, normalizeSelection } from "./core";

// ---------------------------------------------------------------------------
// Render command types
// ---------------------------------------------------------------------------

export interface RenderCommand {
  type: "rect" | "text" | "line";
  x: number;
  y: number;
  width?: number;
  height?: number;
