// ---------------------------------------------------------------------------
// 256-color palette builder (shared with web renderer)
// ---------------------------------------------------------------------------

function build256Palette(theme: Theme): string[] {
  const palette: string[] = new Array(256);

  const themeColors = [
    theme.black,
    theme.red,
    theme.green,
    theme.yellow,
    theme.blue,
    theme.magenta,
    theme.cyan,
    theme.white,
    theme.brightBlack,
    theme.brightRed,
    theme.brightGreen,
    theme.brightYellow,
    theme.brightBlue,
    theme.brightMagenta,
    theme.brightCyan,
    theme.brightWhite,
  ];
  for (let i = 0; i < 16; i++) {
    palette[i] = themeColors[i];
  }

  // 16-231: 6x6x6 color cube
  const cubeLevels = [0, 0x5f, 0x87, 0xaf, 0xd7, 0xff];
  for (let r = 0; r < 6; r++) {
    for (let g = 0; g < 6; g++) {
      for (let b = 0; b < 6; b++) {
        palette[16 + r * 36 + g * 6 + b] =
          `rgb(${cubeLevels[r]},${cubeLevels[g]},${cubeLevels[b]})`;
      }
