          const tmp = fg;
          fg = bg;
          bg = tmp;
        }

        // Cell background (only if non-default)
        if (bg !== theme.background) {
          commands.push({
            type: "rect",
            x,
            y,
            width: cellWidth,
            height: cellHeight,
            color: bg,
          });
        }

