            colEnd = cols - 1;
          }

          commands.push({
            type: "rect",
            x: colStart * cellWidth,
            y: row * cellHeight,
            width: (colEnd - colStart + 1) * cellWidth,
            height: cellHeight,
            color: theme.selectionBackground,
            opacity: 0.5,
          });
        }
